import json


def parse_list(raw, key):
    """Extract list from wrapper dict or return list as-is."""
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            return []
    if isinstance(raw, dict):
        return raw.get(key, []) or []
    if isinstance(raw, list):
        return raw
    return []


tenders = parse_list({clean_tenders_json}, "tenders")
entreprises = parse_list({clean_entreprises_json}, "entreprises")


def score_historique(historique):
    score = 10
    if isinstance(historique, str):
        try:
            historique = json.loads(historique)
        except Exception:
            historique = []
    if not isinstance(historique, list):
        historique = []
    for h in historique:
        if isinstance(h, dict) and h.get("resultat") == "perdu":
            score -= 4
    return max(score, 0)


scores = []

for t in tenders:
    if not isinstance(t, dict):
        continue
    for e in entreprises:
        if not isinstance(e, dict):
            continue

        # Secteur: 35 pts
        secteur = 35 if t.get("secteur") == e.get("secteur") else 0

        # Region: 20 pts
        region = 20 if t.get("region") == e.get("region") else 0

        # Capacite financiere: 20 / 10 / 0 pts
        cap = e.get("capacite_mad", 0)
        mont = t.get("montant_mad", 0)
        try:
            cap = float(cap) if cap is not None else 0
            mont = float(mont) if mont is not None else 0
        except (ValueError, TypeError):
            cap = 0
            mont = 0

        if cap >= mont:
            capacite = 20
        elif cap >= mont * 0.7:
            capacite = 10
        else:
            capacite = 0

        # Qualifications: 15 pts
        req = set(t.get("qualifications_exigees", []) or [])
        ent = set(e.get("qualifications", []) or [])
        qualifications = 15 if req.issubset(ent) else 0

        # Historique: 10 base, -4 per perdu
        historique = score_historique(e.get("historique", []))

        total = secteur + region + capacite + qualifications + historique

        points_perdus = []
        if secteur == 0:
            points_perdus.append("secteur: mismatch (−35)")
        if region == 0:
            points_perdus.append("region: mismatch (−20)")
        if capacite == 0:
            points_perdus.append("capacite: insuffisante (−20)")
        elif capacite == 10:
            points_perdus.append("capacite: partielle (−10)")
        if qualifications == 0:
            missing = list(req - ent)
            points_perdus.append("qualifications: manquantes " + str(missing) + " (−15)")
        if historique < 10:
            points_perdus.append("historique: marchés perdus (−" + str(10 - historique) + ")")

        scores.append(dict(
            reference=t.get("reference"),
            company_id=e.get("company_id"),
            date_calcul=t.get("date_collecte"),
            match_total=total,
            composantes=dict(
                secteur=secteur,
                region=region,
                capacite=capacite,
                qualifications=qualifications,
                historique=historique
            ),
            points_perdus=points_perdus,
            algo_version="1.0.0"
        ))

